import React, { useMemo } from "react";
import { Container } from "react-bootstrap";
import Particle from "../Particle";
import { useInViewOnce } from "../../hooks/useInViewOnce";
import { useTranslation } from "react-i18next";
import { useUmamiStats } from "../../hooks/useUmamiStats";
import { getApiKey } from "../../lib/umamiApi";
import WorldMapHeatmap from "./WorldMapHeatmap";

function flagUrl(code) {
  if (!code || code.length !== 2) return null;
  return `https://flagcdn.com/w40/${code.toLowerCase()}.png`;
}

function formatPathLabel(path) {
  const p = (path || "").toLowerCase();
  if (p.includes("project")) return "Projects";
  if (p.includes("certif")) return "Certifications";
  if (p.includes("resume")) return "Resume";
  if (p.includes("stats")) return "Stats";
  return path || "—";
}

function formatDuration(seconds) {
  if (!seconds) return "0m";
  const m = Math.floor(seconds / 60);
  if (m < 60) return `${m}m`;
  const h = Math.floor(m / 60);
  return `${h}h ${m % 60}m`;
}

function StatsSetup() {
  const { t } = useTranslation();
  return (
    <div className="stats-setup">
      <p>{t("stats.setup_intro")}</p>
      <ol className="stats-setup-steps">
        <li>{t("stats.setup_api")}</li>
        <li>{t("stats.setup_env")}</li>
      </ol>
      <p className="stats-setup-note">{t("stats.setup_period")}</p>
    </div>
  );
}

function StatsDashboard({ data }) {
  const { t } = useTranslation();
  const { summary, active, countries, pages } = data;

  const bounceRate = useMemo(() => {
    if (!summary?.visits) return 0;
    return Math.round((summary.bounces / summary.visits) * 100);
  }, [summary]);

  const countryItems = useMemo(
    () => (countries || []).map((c) => ({ x: c.x, y: c.y, flag: flagUrl(c.x) })),
    [countries]
  );

  const pageItems = useMemo(
    () => (pages || []).map((p) => ({ x: formatPathLabel(p.x), y: p.y })),
    [pages]
  );

  const countryCount = countryItems.length;
  const maxCountry = Math.max(...countryItems.map((i) => i.y), 1);
  const maxPage = Math.max(...pageItems.map((i) => i.y), 1);

  return (
    <>
      <div className="stats-countries-badge">
        <span className="stats-countries-badge-value">{countryCount}</span>
        <span className="stats-countries-badge-label">
          {t("stats.badge_countries", { count: countryCount })}
        </span>
      </div>

      <div className="stats-kpis">
        <div className="stats-kpi">
          <span className="stats-kpi-value">{summary?.visitors ?? "—"}</span>
          <span className="stats-kpi-label">{t("stats.kpi_visitors")}</span>
        </div>
        <div className="stats-kpi">
          <span className="stats-kpi-value">{summary?.visits ?? "—"}</span>
          <span className="stats-kpi-label">{t("stats.kpi_visits")}</span>
        </div>
        <div className="stats-kpi">
          <span className="stats-kpi-value">{summary?.pageviews ?? "—"}</span>
          <span className="stats-kpi-label">{t("stats.kpi_pageviews")}</span>
        </div>
        <div className="stats-kpi">
          <span className="stats-kpi-value">{bounceRate}%</span>
          <span className="stats-kpi-label">{t("stats.kpi_bounce")}</span>
        </div>
        <div className="stats-kpi stats-kpi--live">
          <span className="stats-kpi-value">{active?.visitors ?? 0}</span>
          <span className="stats-kpi-label">{t("stats.kpi_active")}</span>
        </div>
      </div>

      <p className="stats-duration">
        {t("stats.avg_time")}: {formatDuration(summary?.totaltime)}
      </p>

      {summary?.visitors === 0 && (
        <p className="stats-empty-hint">{t("stats.no_data_yet")}</p>
      )}

      <div className="stats-map-block">
        <h3 className="stats-block-title">{t("stats.map_title")}</h3>
        <p className="stats-block-hint">{t("stats.map_hint")}</p>
        <WorldMapHeatmap countries={countries} />
      </div>

      <div className="stats-grid">
        <div className="stats-block">
          <h3 className="stats-block-title">{t("stats.countries_title")}</h3>
          <ul className="stats-bars">
            {countryItems.map((c) => (
              <li key={c.x} className="stats-bar-row stats-bar-row--flag">
                {c.flag ? (
                  <img className="stats-flag" src={c.flag} alt="" width={28} height={20} />
                ) : (
                  <span className="stats-bar-code">{c.x}</span>
                )}
                <span className="stats-bar-label">{c.x}</span>
                <div className="stats-bar-track">
                  <div
                    className="stats-bar-fill"
                    style={{ width: `${(c.y / maxCountry) * 100}%` }}
                  />
                </div>
                <span className="stats-bar-value">{c.y}</span>
              </li>
            ))}
          </ul>
        </div>
        <div className="stats-block">
          <h3 className="stats-block-title">{t("stats.pages_title")}</h3>
          <ul className="stats-bars">
            {pageItems.map((p) => (
              <li key={p.x} className="stats-bar-row">
                <span className="stats-bar-label">{p.x}</span>
                <div className="stats-bar-track">
                  <div
                    className="stats-bar-fill"
                    style={{ width: `${(p.y / maxPage) * 100}%` }}
                  />
                </div>
                <span className="stats-bar-value">{p.y}</span>
              </li>
            ))}
          </ul>
        </div>
      </div>
    </>
  );
}

export default function Stats() {
  const { t } = useTranslation();
  const header = useInViewOnce();
  const apiKey = getApiKey();
  const data = useUmamiStats();

  const showDashboard =
    Boolean(apiKey) &&
    !data.loading &&
    data.error !== "fetch_failed" &&
    data.summary != null;

  return (
    <Container fluid className="stats-section">
      <Particle />
      <Container>
        <div
          ref={header.ref}
          className={`section-card reveal stats-panel ${header.isInView ? "is-visible" : ""}`}
        >
          <div className="section-header">
            <h1 className="section-title">
              {t("stats.title_prefix")}{" "}
              <span className="purple">{t("stats.title_highlight")}</span>
            </h1>
            <p className="section-subtitle">{t("stats.subtitle")}</p>
          </div>

          {!apiKey && <StatsSetup />}

          {apiKey && data.loading && (
            <p className="stats-loading">{t("stats.loading")}</p>
          )}

          {apiKey && data.error === "fetch_failed" && (
            <p className="stats-fallback-msg">{t("stats.api_failed")}</p>
          )}

          {showDashboard && <StatsDashboard data={data} />}

          <p className="stats-footer">{t("stats.footer")}</p>
          <p className="stats-footer stats-footer--hint">{t("stats.path_hint")}</p>
        </div>
      </Container>
    </Container>
  );
}
