const NAME_TO_ISO = {
  "United States": "US",
  "United States of America": "US",
  France: "FR",
  Germany: "DE",
  "United Kingdom": "GB",
  Canada: "CA",
  Belgium: "BE",
  Netherlands: "NL",
  Spain: "ES",
  Italy: "IT",
  Brazil: "BR",
  India: "IN",
  China: "CN",
  Japan: "JP",
  Australia: "AU",
  Switzerland: "CH",
  Poland: "PL",
  Portugal: "PT",
  Sweden: "SE",
  Norway: "NO",
  Denmark: "DK",
  Ireland: "IE",
  Austria: "AT",
  Mexico: "MX",
  Russia: "RU",
  "South Korea": "KR",
  Singapore: "SG",
  Luxembourg: "LU",
};

export function toIsoCode(value) {
  if (!value) return null;
  const v = String(value).trim();
  if (/^[a-z]{2}$/i.test(v)) return v.toUpperCase();
  return NAME_TO_ISO[v] || null;
}

export function buildVisitsByIso(countries) {
  const map = {};
  (countries || []).forEach(({ x, y }) => {
    const iso = toIsoCode(x);
    if (iso) map[iso] = (map[iso] || 0) + (y || 0);
  });
  return map;
}
